/* ==========================================================================
   3D 太陽系シミュレーター (Solar System Simulator) スタイルシート
   宇宙空間・サイバーUI・グラスモーフィズムデザイン
   ========================================================================== */

:root {
  --color-bg: #030712;
  --color-panel-bg: rgba(11, 19, 43, 0.75);
  --color-panel-border: rgba(56, 189, 248, 0.25);
  --color-panel-hover: rgba(56, 189, 248, 0.4);
  --color-primary: #38bdf8;
  --color-primary-glow: rgba(56, 189, 248, 0.4);
  --color-accent: #f59e0b;
  --color-text-main: #f8fafc;
  --color-text-muted: #94a3b8;
  --color-text-dim: #64748b;
  --color-danger: #f43f5e;
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  --font-mono: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --blur-hud: blur(12px);
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --radius-full: 9999px;
  --transition-normal: transform 0.25s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.25s cubic-bezier(0.4, 0, 0.2, 1), border-color 0.25s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.25s cubic-bezier(0.4, 0, 0.2, 1), color 0.25s cubic-bezier(0.4, 0, 0.2, 1);
}

*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

html,
body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background-color: var(--color-bg);
  color: var(--color-text-main);
  font-family: var(--font-sans);
  touch-action: none;
  user-select: none;
  -webkit-user-select: none;
}

/* ==========================================================================
   全画面コンテナ・Canvas
   ========================================================================== */

.app-container {
  position: relative;
  width: 100vw;
  height: 100vh;
  overflow: hidden;
  background: radial-gradient(circle at 50% 50%, #080f26 0%, #030712 100%);
}

.canvas-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 1;
  outline: none;
  cursor: grab;
}

.canvas-container:active {
  cursor: grabbing;
}

/* ==========================================================================
   ヘッダーオーバーレイ
   ========================================================================== */

.header-overlay {
  position: absolute;
  top: 16px;
  left: 20px;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.app-title {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  color: #ffffff;
  text-shadow: 0 0 15px rgba(56, 189, 248, 0.6), 0 2px 4px rgba(0, 0, 0, 0.8);
  display: flex;
  align-items: center;
  gap: 8px;
}

.app-title::before {
  content: "";
  display: inline-block;
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #f59e0b;
  box-shadow: 0 0 10px #f59e0b, 0 0 20px #f59e0b;
}

.app-subtitle {
  font-size: 0.8rem;
  font-family: var(--font-mono);
  color: var(--color-text-muted);
  letter-spacing: 0.04em;
  text-transform: uppercase;
  background: rgba(15, 23, 42, 0.6);
  backdrop-filter: blur(4px);
  padding: 2px 8px;
  border-radius: var(--radius-sm);
  display: inline-block;
  width: fit-content;
  border: 1px solid rgba(255, 255, 255, 0.08);
}

/* ==========================================================================
   HUD操作オーバーレイ & コントロールパネル
   ========================================================================== */

.hud-overlay {
  position: absolute;
  bottom: 20px;
  left: 20px;
  right: 20px;
  z-index: 10;
  pointer-events: none;
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.controls-panel {
  pointer-events: auto;
  background: var(--color-panel-bg);
  backdrop-filter: var(--blur-hud);
  -webkit-backdrop-filter: var(--blur-hud);
  border: 1px solid var(--color-panel-border);
  border-radius: var(--radius-lg);
  padding: 14px 18px;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.6), 0 0 20px rgba(56, 189, 248, 0.1);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
}

.control-group {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}

.control-label {
  font-size: 0.75rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--color-text-muted);
  display: flex;
  align-items: center;
  gap: 6px;
}

/* ボタンスタイル */
.btn-control {
  appearance: none;
  border: 1px solid rgba(255, 255, 255, 0.15);
  background: rgba(255, 255, 255, 0.06);
  color: var(--color-text-main);
  padding: 7px 14px;
  border-radius: var(--radius-md);
  font-size: 0.85rem;
  font-weight: 500;
  font-family: inherit;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  transition: var(--transition-normal);
  white-space: nowrap;
}

.btn-control:hover {
  background: rgba(255, 255, 255, 0.15);
  border-color: rgba(255, 255, 255, 0.35);
  transform: translateY(-1px);
}

.btn-control:active {
  transform: translateY(0);
}

.btn-primary {
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.25) 0%, rgba(14, 165, 233, 0.4) 100%);
  border-color: rgba(56, 189, 248, 0.5);
  color: #38bdf8;
  box-shadow: 0 0 12px rgba(56, 189, 248, 0.2);
}

.btn-primary:hover {
  background: linear-gradient(135deg, rgba(56, 189, 248, 0.4) 0%, rgba(14, 165, 233, 0.6) 100%);
  border-color: #38bdf8;
  color: #ffffff;
  box-shadow: 0 0 16px rgba(56, 189, 248, 0.4);
}

.btn-icon {
  padding: 7px;
  border-radius: var(--radius-md);
  width: 36px;
  height: 36px;
}

.btn-reset {
  border-color: rgba(148, 163, 184, 0.3);
  color: var(--color-text-muted);
}

.btn-reset:hover {
  color: var(--color-text-main);
  border-color: var(--color-text-muted);
}

/* スピードスライダー */
.speed-slider {
  appearance: none;
  -webkit-appearance: none;
  width: 110px;
  height: 6px;
  border-radius: var(--radius-full);
  background: rgba(255, 255, 255, 0.15);
  outline: none;
  cursor: pointer;
  transition: var(--transition-normal);
}

.speed-slider:hover {
  background: rgba(255, 255, 255, 0.25);
}

.speed-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #38bdf8;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
  cursor: pointer;
  transition: transform 0.15s ease, background-color 0.15s ease;
}

.speed-slider::-webkit-slider-thumb:hover {
  transform: scale(1.25);
  background: #7dd3fc;
}

.speed-slider::-moz-range-thumb {
  width: 16px;
  height: 16px;
  border-radius: 50%;
  background: #38bdf8;
  border: none;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.8);
  cursor: pointer;
}

/* チェックボックス */
.checkbox-label {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: 0.8rem;
  color: var(--color-text-muted);
  cursor: pointer;
  user-select: none;
  transition: var(--transition-normal);
}

.checkbox-label:hover {
  color: var(--color-text-main);
}

.checkbox-input {
  appearance: none;
  -webkit-appearance: none;
  width: 16px;
  height: 16px;
  border: 1px solid rgba(255, 255, 255, 0.3);
  border-radius: var(--radius-sm);
  background: rgba(255, 255, 255, 0.05);
  outline: none;
  cursor: pointer;
  display: grid;
  place-content: center;
  transition: var(--transition-normal);
}

.checkbox-input:checked {
  background: #38bdf8;
  border-color: #38bdf8;
  box-shadow: 0 0 8px rgba(56, 189, 248, 0.5);
}

.checkbox-input:checked::before {
  content: "";
  width: 8px;
  height: 5px;
  border-left: 2px solid #030712;
  border-bottom: 2px solid #030712;
  transform: rotate(-45deg) translate(1px, -1px);
}

/* ==========================================================================
   惑星クイック選択ナビゲーション (HUD)
   ========================================================================== */

.planet-selector {
  display: flex;
  align-items: center;
  width: 100%;
  overflow: hidden;
}

.planet-quick-nav {
  pointer-events: auto;
  display: flex;
  align-items: center;
  gap: 8px;
  overflow-x: auto;
  padding: 4px 2px 8px 2px;
  scrollbar-width: thin;
  scrollbar-color: rgba(56, 189, 248, 0.3) transparent;
  width: 100%;
}

.planet-quick-nav::-webkit-scrollbar {
  height: 4px;
}

.planet-quick-nav::-webkit-scrollbar-track {
  background: transparent;
}

.planet-quick-nav::-webkit-scrollbar-thumb {
  background: rgba(56, 189, 248, 0.3);
  border-radius: 4px;
}

.planet-chip {
  appearance: none;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(15, 23, 42, 0.7);
  backdrop-filter: blur(8px);
  color: var(--color-text-muted);
  padding: 6px 14px;
  border-radius: var(--radius-full);
  font-size: 0.8rem;
  font-weight: 500;
  cursor: pointer;
  white-space: nowrap;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: var(--transition-normal);
  flex-shrink: 0;
}

.planet-chip::before {
  content: "";
  display: inline-block;
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: currentColor;
  box-shadow: 0 0 6px currentColor;
}

.planet-chip:hover {
  background: rgba(30, 41, 59, 0.9);
  color: var(--color-text-main);
  border-color: rgba(56, 189, 248, 0.4);
  transform: translateY(-2px);
}

.planet-chip-active {
  background: rgba(56, 189, 248, 0.2);
  border-color: #38bdf8;
  color: #ffffff;
  box-shadow: 0 0 14px rgba(56, 189, 248, 0.35);
  font-weight: 600;
}

.planet-chip-active::before {
  box-shadow: 0 0 10px #38bdf8;
}

/* ガイドテキスト */
.guide-text {
  font-size: 0.75rem;
  color: var(--color-text-dim);
  text-align: center;
  pointer-events: none;
  font-family: var(--font-mono);
  letter-spacing: 0.02em;
}

/* ==========================================================================
   惑星詳細スペック解説パネル (Planet Info Card)
   ========================================================================== */

.planet-info-card {
  position: absolute;
  top: 20px;
  right: 20px;
  z-index: 20;
  width: 340px;
  max-width: calc(100vw - 40px);
  max-height: calc(100vh - 160px);
  overflow-y: auto;
  background: var(--color-panel-bg);
  backdrop-filter: var(--blur-hud);
  -webkit-backdrop-filter: var(--blur-hud);
  border: 1px solid var(--color-panel-border);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: 0 20px 40px rgba(0, 0, 0, 0.7), 0 0 25px rgba(56, 189, 248, 0.15);
  display: flex;
  flex-direction: column;
  gap: 16px;
  animation: fadeInRight 0.3s cubic-bezier(0.16, 1, 0.3, 1) forwards;
  scrollbar-width: thin;
  scrollbar-color: rgba(56, 189, 248, 0.3) transparent;
}

.planet-info-card::-webkit-scrollbar {
  width: 4px;
}

.planet-info-card::-webkit-scrollbar-thumb {
  background: rgba(56, 189, 248, 0.3);
  border-radius: 4px;
}

@keyframes fadeInRight {
  from {
    opacity: 0;
    transform: translateX(24px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

.planet-info-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  padding-bottom: 12px;
}

.planet-info-title {
  font-size: 1.4rem;
  font-weight: 700;
  color: var(--color-text-main);
  display: flex;
  align-items: center;
  gap: 8px;
}

.planet-info-english {
  font-size: 0.8rem;
  font-family: var(--font-mono);
  color: var(--color-text-muted);
  font-weight: normal;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-top: 2px;
}

.close-btn {
  appearance: none;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.15);
  color: var(--color-text-muted);
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1rem;
  cursor: pointer;
  transition: var(--transition-normal);
  flex-shrink: 0;
}

.close-btn:hover {
  background: rgba(244, 63, 94, 0.2);
  border-color: var(--color-danger);
  color: var(--color-danger);
  transform: rotate(90deg);
}

.planet-badge {
  display: inline-block;
  padding: 3px 8px;
  border-radius: var(--radius-sm);
  font-size: 0.7rem;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  background: rgba(56, 189, 248, 0.15);
  color: #38bdf8;
  border: 1px solid rgba(56, 189, 248, 0.3);
  margin-left: 6px;
  vertical-align: middle;
}

.planet-desc {
  font-size: 0.85rem;
  line-height: 1.6;
  color: #cbd5e1;
  background: rgba(0, 0, 0, 0.25);
  padding: 10px 12px;
  border-radius: var(--radius-md);
  border-left: 3px solid #38bdf8;
}

/* スペックグリッド */
.specs-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 10px;
}

.spec-item {
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: var(--radius-md);
  padding: 10px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.spec-label {
  font-size: 0.7rem;
  color: var(--color-text-muted);
  font-weight: 500;
  letter-spacing: 0.03em;
}

.spec-value {
  font-size: 0.95rem;
  font-weight: 700;
  font-family: var(--font-mono);
  color: var(--color-text-main);
  word-break: break-all;
}

/* ==========================================================================
   レスポンシブ対応 (モバイル・タブレット)
   ========================================================================== */

@media (max-width: 768px) {
  .header-overlay {
    top: 12px;
    left: 14px;
  }

  .app-title {
    font-size: 1.15rem;
  }

  .app-subtitle {
    font-size: 0.7rem;
  }

  .hud-overlay {
    bottom: 12px;
    left: 12px;
    right: 12px;
    gap: 8px;
  }

  .controls-panel {
    padding: 10px 12px;
    gap: 8px;
  }

  .control-group {
    gap: 8px;
    width: 100%;
    justify-content: space-between;
  }

  .speed-slider {
    width: 80px;
  }

  .btn-control {
    font-size: 0.75rem;
    padding: 6px 10px;
    min-width: 76px;
  }

  .planet-chip {
    padding: 5px 10px;
    font-size: 0.75rem;
  }

  .planet-info-card {
    top: auto;
    bottom: 160px;
    right: 12px;
    left: 12px;
    width: auto;
    max-width: none;
    max-height: 48vh;
    padding: 14px;
    gap: 12px;
  }

  .specs-grid {
    grid-template-columns: 1fr 1fr;
    gap: 6px;
  }

  .spec-item {
    padding: 6px 8px;
  }

  .spec-value {
    font-size: 0.85rem;
  }

  .guide-text {
    display: none;
  }
}

@media (max-width: 480px) {
  .controls-panel {
    display: flex;
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    padding: 10px;
  }

  .control-group {
    width: 100%;
    justify-content: space-between;
    gap: 6px;
  }

  .control-label {
    font-size: 0.7rem;
  }

  .btn-control {
    min-width: 68px;
    font-size: 0.72rem;
    padding: 6px 8px;
    white-space: nowrap;
    flex-shrink: 0;
  }

  .speed-slider {
    width: 70px;
  }

  .checkbox-label {
    font-size: 0.75rem;
  }
}

export type LabelDisplayMode = 'all' | 'hover' | 'selected';

export interface MoonData {
  name: string;
  radius: number;
  distance: number;
  speed: number;
  color: string;
}

export interface RingData {
  innerRadius: number;
  outerRadius: number;
  color: string;
}

export interface PlanetData {
  id: string;
  name: string;
  englishName: string;
  radius: number;
  distance: number;
  focusDistance?: number;
  color: string;
  speed: number;
  rotationSpeed: number;
  ring?: RingData;
  moons?: MoonData[];
  description: string;
  diameterKm: string;
  orbitPeriodDays: string;
  rotationPeriodHours: string;
  temperature: string;
}

export interface SolarSystemSettings {
  isPlaying: boolean;
  speedMultiplier: number;
  showOrbits: boolean;
  showLabels: boolean;
  labelMode?: LabelDisplayMode;
  selectedPlanetId: string | null;
}

import { useEffect, useRef } from 'react';
import * as THREE from 'three';
import { PlanetData, SolarSystemSettings } from './types';
import { ALL_CELESTIAL_BODIES, PLANETS_DATA, SUN_DATA } from './solarData';

interface SolarCanvasProps {
  settings: SolarSystemSettings;
  onSelectPlanet: (planetId: string | null) => void;
}

interface PlanetObjectRef {
  id: string;
  data: PlanetData;
  pivot: THREE.Group;
  mesh: THREE.Mesh;
  hitMesh: THREE.Mesh;
  labelSprite: THREE.Sprite;
  orbitAngle: number;
  rotationAngle: number;
  ringMesh?: THREE.Mesh;
  moons?: {
    mesh: THREE.Mesh;
    pivot: THREE.Group;
    angle: number;
    speed: number;
  }[];
}

/**
 * テキスト描画Canvasからスプライト用テクスチャを生成
 */
function createTextSprite(text: string, subText: string, color: string): THREE.Sprite {
  const canvas = document.createElement('canvas');
  canvas.width = 256;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');

  if (ctx) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // 背景の半透明カプセル
    ctx.fillStyle = 'rgba(3, 7, 18, 0.75)';
    ctx.strokeStyle = 'rgba(56, 189, 248, 0.4)';
    ctx.lineWidth = 2;
    const x = 16;
    const y = 16;
    const w = canvas.width - 32;
    const h = canvas.height - 32;
    const r = 24;

    ctx.beginPath();
    ctx.moveTo(x + r, y);
    ctx.lineTo(x + w - r, y);
    ctx.quadraticCurveTo(x + w, y, x + w, y + r);
    ctx.lineTo(x + w, y + h - r);
    ctx.quadraticCurveTo(x + w, y + h, x + w - r, y + h);
    ctx.lineTo(x + r, y + h);
    ctx.quadraticCurveTo(x, y + h, x, y + h - r);
    ctx.lineTo(x, y + r);
    ctx.quadraticCurveTo(x, y, x + r, y);
    ctx.closePath();
    ctx.fill();
    ctx.stroke();

    // メイン天体名
    ctx.font = 'bold 28px -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillStyle = '#ffffff';
    ctx.fillText(text, canvas.width / 2, 48);

    // 英語名
    ctx.font = '500 18px ui-monospace, Menlo, Monaco, Consolas, monospace';
    ctx.fillStyle = color;
    ctx.fillText(subText, canvas.width / 2, 78);
  }

  const texture = new THREE.CanvasTexture(canvas);
  texture.minFilter = THREE.LinearFilter;
  const spriteMaterial = new THREE.SpriteMaterial({
    map: texture,
    transparent: true,
    depthTest: false,
    depthWrite: false
  });
  const sprite = new THREE.Sprite(spriteMaterial);
  sprite.scale.set(10, 5, 1);
  return sprite;
}

const SolarCanvas = ({ settings, onSelectPlanet }: SolarCanvasProps) => {
  const mountRef = useRef<HTMLDivElement>(null);
  const settingsRef = useRef(settings);
  settingsRef.current = settings;

  const onSelectPlanetRef = useRef(onSelectPlanet);
  onSelectPlanetRef.current = onSelectPlanet;

  useEffect(() => {
    const container = mountRef.current;
    if (!container) return;

    // --- シーン・カメラ・レンダラーのセットアップ ---
    const scene = new THREE.Scene();
    scene.fog = new THREE.FogExp2(0x030712, 0.0018);

    const camera = new THREE.PerspectiveCamera(
      45,
      container.clientWidth / container.clientHeight,
      0.5,
      2500
    );
    camera.position.set(0, 110, 160);

    const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: false });
    renderer.setSize(container.clientWidth, container.clientHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.2;
    container.appendChild(renderer.domElement);

    // --- ライト構成 ---
    const ambientLight = new THREE.AmbientLight(0x223344, 0.6);
    scene.add(ambientLight);

    const sunLight = new THREE.PointLight(0xfff7ed, 3.5, 900, 0.4);
    sunLight.position.set(0, 0, 0);
    scene.add(sunLight);

    // 補助微光ライト（太陽の真裏が暗黒になりすぎないよう調整）
    const fillLight = new THREE.HemisphereLight(0x1e293b, 0x020617, 0.4);
    scene.add(fillLight);

    // --- 星空背景パーティクル ---
    const starCount = 3500;
    const starGeometry = new THREE.BufferGeometry();
    const starPositions = new Float32Array(starCount * 3);
    const starColors = new Float32Array(starCount * 3);

    const starColorPalette = [
      new THREE.Color('#38bdf8'),
      new THREE.Color('#ffffff'),
      new THREE.Color('#fef08a'),
      new THREE.Color('#cbd5e1')
    ];

    for (let i = 0; i < starCount; i++) {
      const radius = 600 + Math.random() * 800;
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.acos(Math.random() * 2 - 1);

      starPositions[i * 3] = radius * Math.sin(phi) * Math.cos(theta);
      starPositions[i * 3 + 1] = radius * Math.sin(phi) * Math.sin(theta);
      starPositions[i * 3 + 2] = radius * Math.cos(phi);

      const color = starColorPalette[Math.floor(Math.random() * starColorPalette.length)];
      starColors[i * 3] = color.r;
      starColors[i * 3 + 1] = color.g;
      starColors[i * 3 + 2] = color.b;
    }

    starGeometry.setAttribute('position', new THREE.BufferAttribute(starPositions, 3));
    starGeometry.setAttribute('color', new THREE.BufferAttribute(starColors, 3));

    const starMaterial = new THREE.PointsMaterial({
      size: 1.8,
      vertexColors: true,
      transparent: true,
      opacity: 0.85
    });
    const starField = new THREE.Points(starGeometry, starMaterial);
    scene.add(starField);

    // --- ラベルグループ & 軌道グループ ---
    const labelsGroup = new THREE.Group();
    scene.add(labelsGroup);

    const orbitLinesGroup = new THREE.Group();
    scene.add(orbitLinesGroup);

    // クリック判定対象リスト（ヒットボックスメッシュ）
    const interactiveMeshes: THREE.Mesh[] = [];

    // --- 太陽の作成 ---
    const sunGeometry = new THREE.SphereGeometry(SUN_DATA.radius, 48, 48);
    const sunMaterial = new THREE.MeshBasicMaterial({
      color: new THREE.Color(SUN_DATA.color)
    });
    const sunMesh = new THREE.Mesh(sunGeometry, sunMaterial);
    sunMesh.userData = { id: SUN_DATA.id };
    scene.add(sunMesh);

    // 太陽の外部コロナ・グローエフェクト
    const glowGeometry = new THREE.SphereGeometry(SUN_DATA.radius * 1.25, 32, 32);
    const glowMaterial = new THREE.MeshBasicMaterial({
      color: 0xf59e0b,
      transparent: true,
      opacity: 0.25,
      side: THREE.BackSide
    });
    const sunGlow = new THREE.Mesh(glowGeometry, glowMaterial);
    scene.add(sunGlow);

    // 太陽用ヒットボックス（十分なクリック判定領域）
    const sunHitGeo = new THREE.SphereGeometry(SUN_DATA.radius * 1.2, 16, 16);
    const hitMat = new THREE.MeshBasicMaterial({
      transparent: true,
      opacity: 0,
      depthWrite: false
    });
    const sunHitMesh = new THREE.Mesh(sunHitGeo, hitMat);
    sunHitMesh.userData = { id: SUN_DATA.id };
    scene.add(sunHitMesh);
    interactiveMeshes.push(sunHitMesh);

    // 太陽用ラベル
    const sunLabel = createTextSprite(SUN_DATA.name, SUN_DATA.englishName, SUN_DATA.color);
    sunLabel.position.set(0, SUN_DATA.radius + 3.2, 0);
    labelsGroup.add(sunLabel);

    // --- 惑星群の作成 ---
    const planetObjects: PlanetObjectRef[] = [];

    PLANETS_DATA.forEach((data, index) => {
      // 軌道ラインの生成
      const curve = new THREE.EllipseCurve(
        0, 0,
        data.distance, data.distance,
        0, 2 * Math.PI,
        false,
        0
      );
      const points = curve.getPoints(128);
      const orbitGeometry = new THREE.BufferGeometry().setFromPoints(
        points.map(p => new THREE.Vector3(p.x, 0, p.y))
      );
      const orbitMaterial = new THREE.LineBasicMaterial({
        color: 0x38bdf8,
        transparent: true,
        opacity: 0.22
      });
      const orbitLine = new THREE.LineLoop(orbitGeometry, orbitMaterial);
      orbitLinesGroup.add(orbitLine);

      // 公転用ピボット
      const pivot = new THREE.Group();
      scene.add(pivot);

      // 惑星本体
      const planetGeometry = new THREE.SphereGeometry(data.radius, 32, 32);
      const planetMaterial = new THREE.MeshStandardMaterial({
        color: new THREE.Color(data.color),
        roughness: 0.7,
        metalness: 0.1
      });
      const planetMesh = new THREE.Mesh(planetGeometry, planetMaterial);
      planetMesh.position.set(data.distance, 0, 0);
      planetMesh.userData = { id: data.id };
      pivot.add(planetMesh);

      // クリック判定用不可視拡大ヒットボックス（水星や火星など小さな天体も確実にタップ可能に）
      const hitRadius = Math.max(data.radius * 1.6, 2.8);
      const planetHitGeo = new THREE.SphereGeometry(hitRadius, 16, 16);
      const planetHitMesh = new THREE.Mesh(planetHitGeo, hitMat);
      planetHitMesh.position.set(data.distance, 0, 0);
      planetHitMesh.userData = { id: data.id };
      pivot.add(planetHitMesh);
      interactiveMeshes.push(planetHitMesh);

      // 天王星などの自転軸傾斜角
      if (data.id === 'uranus') {
        planetMesh.rotation.z = THREE.MathUtils.degToRad(97.7);
      } else if (data.id === 'earth') {
        planetMesh.rotation.z = THREE.MathUtils.degToRad(23.4);
      } else if (data.id === 'mars') {
        planetMesh.rotation.z = THREE.MathUtils.degToRad(25.2);
      } else if (data.id === 'saturn') {
        planetMesh.rotation.z = THREE.MathUtils.degToRad(26.7);
      }

      let ringMesh: THREE.Mesh | undefined;
      // 土星または天王星のリング
      if (data.ring) {
        const ringGeo = new THREE.RingGeometry(data.ring.innerRadius, data.ring.outerRadius, 64);
        const ringMat = new THREE.MeshStandardMaterial({
          color: new THREE.Color(data.ring.color),
          side: THREE.DoubleSide,
          transparent: true,
          opacity: 0.8,
          roughness: 0.5
        });
        ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = Math.PI / 2;
        planetMesh.add(ringMesh);
      }

      // 衛星（地球の月など）
      let moonsList: PlanetObjectRef['moons'] = undefined;
      if (data.moons && data.moons.length > 0) {
        moonsList = [];
        data.moons.forEach(m => {
          const moonPivot = new THREE.Group();
          planetMesh.add(moonPivot);

          const moonGeo = new THREE.SphereGeometry(m.radius, 16, 16);
          const moonMat = new THREE.MeshStandardMaterial({
            color: new THREE.Color(m.color),
            roughness: 0.9
          });
          const moonMesh = new THREE.Mesh(moonGeo, moonMat);
          moonMesh.position.set(m.distance, 0, 0);
          moonPivot.add(moonMesh);

          moonsList?.push({
            mesh: moonMesh,
            pivot: moonPivot,
            angle: Math.random() * Math.PI * 2,
            speed: m.speed
          });
        });
      }

      // 惑星名ラベルスプライト
      const labelSprite = createTextSprite(data.name, data.englishName, data.color);
      labelsGroup.add(labelSprite);

      // 初期公転角度をばらけさせる
      const initialAngle = (index * (Math.PI * 2)) / PLANETS_DATA.length + 0.3;
      pivot.rotation.y = initialAngle;

      planetObjects.push({
        id: data.id,
        data,
        pivot,
        mesh: planetMesh,
        hitMesh: planetHitMesh,
        labelSprite,
        orbitAngle: initialAngle,
        rotationAngle: 0,
        ringMesh,
        moons: moonsList
      });
    });

    // --- カメラ操作・インタラクション状態 ---
    const cameraTarget = new THREE.Vector3(0, 0, 0);
    const cameraLookAt = new THREE.Vector3(0, 0, 0);

    let isPointerDown = false;
    let hasPointerMoved = false;
    let pointerStartX = 0;
    let pointerStartY = 0;
    const spherical = new THREE.Spherical(200, Math.PI / 3.2, 0);

    let touchStartDist = 0;

    // 選択天体ワールド座標追従用
    const currentPlanetWorldPos = new THREE.Vector3();

    const updateCameraFromSpherical = () => {
      const offset = new THREE.Vector3().setFromSpherical(spherical);
      camera.position.copy(cameraLookAt).add(offset);
      camera.lookAt(cameraLookAt);
    };
    updateCameraFromSpherical();

    // マウス・タッチ制御イベント
    const handlePointerDown = (e: PointerEvent) => {
      isPointerDown = true;
      hasPointerMoved = false;
      pointerStartX = e.clientX;
      pointerStartY = e.clientY;
    };

    const handlePointerMove = (e: PointerEvent) => {
      if (!isPointerDown) return;
      const deltaX = e.clientX - pointerStartX;
      const deltaY = e.clientY - pointerStartY;

      if (Math.abs(deltaX) > 4 || Math.abs(deltaY) > 4) {
        hasPointerMoved = true;
      }

      spherical.theta -= deltaX * 0.005;
      spherical.phi = Math.max(0.1, Math.min(Math.PI / 2.05, spherical.phi - deltaY * 0.005));

      pointerStartX = e.clientX;
      pointerStartY = e.clientY;
    };

    const handlePointerUp = (e: PointerEvent) => {
      if (isPointerDown && !hasPointerMoved) {
        // クリック/タップ判定 -> Raycaster
        const rect = container.getBoundingClientRect();
        const x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
        const y = -((e.clientY - rect.top) / rect.height) * 2 + 1;

        const raycaster = new THREE.Raycaster();
        raycaster.setFromCamera(new THREE.Vector2(x, y), camera);

        const intersects = raycaster.intersectObjects(interactiveMeshes, false);
        if (intersects.length > 0) {
          const hit = intersects[0].object;
          const hitId = hit.userData.id as string | undefined;
          if (hitId) {
            onSelectPlanetRef.current(hitId);
          }
        }
      }
      isPointerDown = false;
    };

    const handleWheel = (e: WheelEvent) => {
      e.preventDefault();
      spherical.radius = Math.max(15, Math.min(800, spherical.radius + e.deltaY * 0.25));
    };

    // タッチピンチズーム対応
    const handleTouchStart = (e: TouchEvent) => {
      if (e.touches.length === 2) {
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        touchStartDist = Math.hypot(dx, dy);
      }
    };

    const handleTouchMove = (e: TouchEvent) => {
      if (e.touches.length === 2) {
        const dx = e.touches[0].clientX - e.touches[1].clientX;
        const dy = e.touches[0].clientY - e.touches[1].clientY;
        const dist = Math.hypot(dx, dy);
        const factor = touchStartDist / dist;
        spherical.radius = Math.max(15, Math.min(800, spherical.radius * (1 + (factor - 1) * 0.1)));
        touchStartDist = dist;
      }
    };

    container.addEventListener('pointerdown', handlePointerDown);
    window.addEventListener('pointermove', handlePointerMove);
    window.addEventListener('pointerup', handlePointerUp);
    container.addEventListener('wheel', handleWheel, { passive: false });
    container.addEventListener('touchstart', handleTouchStart, { passive: true });
    container.addEventListener('touchmove', handleTouchMove, { passive: true });

    // ウィンドウリサイズ対応
    const handleResize = () => {
      if (!container) return;
      camera.aspect = container.clientWidth / container.clientHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(container.clientWidth, container.clientHeight);
    };
    window.addEventListener('resize', handleResize);

    // --- メインアニメーションループ ---
    let animationFrameId: number;
    let lastTime = performance.now();
    const tempVec = new THREE.Vector3();

    const animate = () => {
      animationFrameId = requestAnimationFrame(animate);

      const currentTime = performance.now();
      const delta = Math.min((currentTime - lastTime) / 1000, 0.1);
      lastTime = currentTime;

      const { isPlaying, speedMultiplier, showOrbits, showLabels, selectedPlanetId } = settingsRef.current;

      // 軌道線およびラベル表示状態の反映
      orbitLinesGroup.visible = showOrbits;
      labelsGroup.visible = showLabels;

      // 太陽自転
      if (isPlaying) {
        sunMesh.rotation.y += SUN_DATA.rotationSpeed * speedMultiplier;
        sunGlow.rotation.y += SUN_DATA.rotationSpeed * 0.5 * speedMultiplier;
      }

      // 惑星公転・自転
      planetObjects.forEach(p => {
        if (isPlaying) {
          p.orbitAngle += p.data.speed * speedMultiplier * delta * 60;
          p.pivot.rotation.y = p.orbitAngle;

          p.rotationAngle += p.data.rotationSpeed * speedMultiplier * delta * 60;
          p.mesh.rotation.y = p.rotationAngle;

          // 衛星の公転
          if (p.moons) {
            p.moons.forEach(m => {
              m.angle += m.speed * speedMultiplier * delta * 60;
              m.pivot.rotation.y = m.angle;
            });
          }
        }

        // ラベル位置のリアルタイム更新（自転で回転しないよう親ではなくlabelsGroup内で追随）
        p.mesh.getWorldPosition(tempVec);
        p.labelSprite.position.set(tempVec.x, tempVec.y + p.data.radius + 2.2, tempVec.z);
      });

      // 選択天体フォーカス追尾ロジック
      if (selectedPlanetId) {
        if (selectedPlanetId === 'sun') {
          cameraTarget.set(0, 0, 0);
          const desiredRadius = SUN_DATA.focusDistance ?? 40;
          if (Math.abs(spherical.radius - desiredRadius) > 0.5) {
            spherical.radius = THREE.MathUtils.lerp(spherical.radius, desiredRadius, 0.05);
          }
        } else {
          const targetObj = planetObjects.find(p => p.id === selectedPlanetId);
          if (targetObj) {
            targetObj.mesh.getWorldPosition(currentPlanetWorldPos);
            cameraTarget.copy(currentPlanetWorldPos);

            // 惑星定義の最適フォーカス距離を優先参照し、未定義なら大きさから算出
            const desiredRadius = targetObj.data.focusDistance ?? Math.max(targetObj.data.radius * 5.5, 16);
            if (Math.abs(spherical.radius - desiredRadius) > 0.5) {
              spherical.radius = THREE.MathUtils.lerp(spherical.radius, desiredRadius, 0.06);
            }
          }
        }
      } else {
        // 未選択時は太陽系全体中央を注視
        cameraTarget.set(0, 0, 0);
      }

      // カメラ注視点のスムーズな補間
      cameraLookAt.lerp(cameraTarget, 0.08);

      // カメラ位置の適用
      updateCameraFromSpherical();

      renderer.render(scene, camera);
    };

    animate();

    return () => {
      cancelAnimationFrame(animationFrameId);
      window.removeEventListener('resize', handleResize);
      container.removeEventListener('pointerdown', handlePointerDown);
      window.removeEventListener('pointermove', handlePointerMove);
      window.removeEventListener('pointerup', handlePointerUp);
      container.removeEventListener('wheel', handleWheel);
      container.removeEventListener('touchstart', handleTouchStart);
      container.removeEventListener('touchmove', handleTouchMove);

      if (container.contains(renderer.domElement)) {
        container.removeChild(renderer.domElement);
      }

      // 包括的リソース解放（メモリリーク防止）
      scene.traverse((obj) => {
        const meshObj = obj as THREE.Mesh;
        if (meshObj.geometry) {
          meshObj.geometry.dispose();
        }
        if (meshObj.material) {
          if (Array.isArray(meshObj.material)) {
            meshObj.material.forEach((mat) => {
              if ('map' in mat && mat.map) {
                mat.map.dispose();
              }
              mat.dispose();
            });
          } else {
            const singleMat = meshObj.material as THREE.Material & { map?: THREE.Texture };
            if (singleMat.map) {
              singleMat.map.dispose();
            }
            singleMat.dispose();
          }
        }
      });

      hitMat.dispose();
      renderer.dispose();
    };
  }, []);

  return <div ref={mountRef} className="canvas-container" />;
};

export default SolarCanvas;

import { FC, ChangeEvent, useRef } from 'react';
import { Play, Pause, RotateCcw, Orbit, Tag, ChevronLeft, ChevronRight } from 'lucide-react';
import { SolarSystemSettings } from './types';
import { ALL_CELESTIAL_BODIES } from './solarData';

interface ControlsProps {
  settings: SolarSystemSettings;
  onUpdateSettings: (settings: Partial<SolarSystemSettings>) => void;
  onResetView: () => void;
}

const Controls: FC<ControlsProps> = ({
  settings,
  onUpdateSettings,
  onResetView
}) => {
  const scrollContainerRef = useRef<HTMLDivElement>(null);

  const togglePlay = () => {
    onUpdateSettings({ isPlaying: !settings.isPlaying });
  };

  const handleSpeedChange = (e: ChangeEvent<HTMLInputElement>) => {
    onUpdateSettings({ speedMultiplier: parseFloat(e.target.value) });
  };

  const handleToggleOrbits = (e: ChangeEvent<HTMLInputElement>) => {
    onUpdateSettings({ showOrbits: e.target.checked });
  };

  const handleToggleLabels = (e: ChangeEvent<HTMLInputElement>) => {
    onUpdateSettings({ showLabels: e.target.checked });
  };

  const handleSelectPlanet = (id: string) => {
    if (settings.selectedPlanetId === id) {
      onUpdateSettings({ selectedPlanetId: null });
    } else {
      onUpdateSettings({ selectedPlanetId: id });
    }
  };

  const handleScrollNav = (direction: 'left' | 'right') => {
    if (scrollContainerRef.current) {
      const scrollAmount = direction === 'left' ? -180 : 180;
      scrollContainerRef.current.scrollBy({ left: scrollAmount, behavior: 'smooth' });
    }
  };

  return (
    <div className="hud-overlay">
      {/* 天体クイック選択ナビゲーション */}
      <div className="planet-selector">
        <button
          type="button"
          className="btn-control btn-icon"
          style={{ flexShrink: 0, marginRight: '4px' }}
          onClick={() => handleScrollNav('left')}
          aria-label="惑星一覧を左へスクロール"
          title="左へスクロール"
        >
          <ChevronLeft size={16} />
        </button>

        <div className="planet-quick-nav" ref={scrollContainerRef}>
          {ALL_CELESTIAL_BODIES.map((body) => {
            const isSelected = settings.selectedPlanetId === body.id;
            return (
              <button
                key={body.id}
                type="button"
                className={isSelected ? 'planet-chip planet-chip-active' : 'planet-chip'}
                style={{ color: isSelected ? '#ffffff' : body.color }}
                onClick={() => handleSelectPlanet(body.id)}
                aria-pressed={isSelected}
                title={`${body.name} (${body.englishName}) を追尾`}
              >
                {body.name}
              </button>
            );
          })}
        </div>

        <button
          type="button"
          className="btn-control btn-icon"
          style={{ flexShrink: 0, marginLeft: '4px' }}
          onClick={() => handleScrollNav('right')}
          aria-label="惑星一覧を右へスクロール"
          title="右へスクロール"
        >
          <ChevronRight size={16} />
        </button>
      </div>

      <div className="controls-panel">
        {/* 再生/一時停止 & 速度調整 */}
        <div className="control-group">
          <button
            type="button"
            className={settings.isPlaying ? 'btn-control btn-primary' : 'btn-control'}
            onClick={togglePlay}
            aria-pressed={settings.isPlaying}
            aria-label={settings.isPlaying ? '一時停止 (Space)' : '再開 (Space)'}
            title={settings.isPlaying ? '一時停止 (Space)' : '再開 (Space)'}
          >
            {settings.isPlaying ? <Pause size={16} /> : <Play size={16} />}
            <span>{settings.isPlaying ? '一時停止' : '再開'}</span>
          </button>

          <div className="control-group">
            <span className="control-label">速度: {settings.speedMultiplier.toFixed(1)}x</span>
            <input
              type="range"
              min="0.1"
              max="5.0"
              step="0.1"
              value={settings.speedMultiplier}
              onChange={handleSpeedChange}
              className="speed-slider"
              aria-label="シミュレーション速度"
            />
          </div>
        </div>

        {/* 軌道線・ラベル表示切り替え */}
        <div className="control-group">
          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={settings.showOrbits}
              onChange={handleToggleOrbits}
              className="checkbox-input"
            />
            <Orbit size={14} />
            <span>軌道線</span>
          </label>

          <label className="checkbox-label">
            <input
              type="checkbox"
              checked={settings.showLabels}
              onChange={handleToggleLabels}
              className="checkbox-input"
            />
            <Tag size={14} />
            <span>名前</span>
          </label>
        </div>

        {/* 俯瞰リセットボタン */}
        <div className="control-group">
          <button
            type="button"
            className="btn-control btn-reset"
            onClick={onResetView}
            title="視点を太陽系全体へリセット"
          >
            <RotateCcw size={15} />
            <span>全体俯瞰</span>
          </button>
        </div>
      </div>

      <div className="guide-text">
        ドラッグで360°回転 / ホイール・ピンチでズーム / 惑星をクリックで追尾 / Spaceで再生・停止
      </div>
    </div>
  );
};

export default Controls;

import { FC, useEffect, useRef } from 'react';
import { X, ExternalLink, Disc, Moon } from 'lucide-react';
import { PlanetData } from './types';

interface PlanetInfoPanelProps {
  planet: PlanetData | null;
  onClose: () => void;
}

const PlanetInfoPanel: FC<PlanetInfoPanelProps> = ({ planet, onClose }) => {
  const panelRef = useRef<HTMLDivElement>(null);

  // Escapeキー押下でパネルを閉じるアクセシビリティ対応
  useEffect(() => {
    if (!planet) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'Escape') {
        e.preventDefault();
        onClose();
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [planet, onClose]);

  if (!planet) return null;

  return (
    <div
      ref={panelRef}
      className="planet-info-card"
      role="dialog"
      aria-modal="false"
      aria-labelledby="planet-title"
    >
      <div className="planet-info-header">
        <div>
          <div className="planet-info-title" id="planet-title">
            <span style={{ color: planet.color }}>●</span>
            {planet.name}
            <span className="planet-badge">{planet.id === 'sun' ? '恒星' : '惑星'}</span>
          </div>
          <div className="planet-info-english">{planet.englishName}</div>
        </div>
        <button
          type="button"
          className="close-btn"
          onClick={onClose}
          aria-label="パネルを閉じる (Esc)"
          title="パネルを閉じる (Esc)"
        >
          <X size={18} />
        </button>
      </div>

      <div className="planet-desc">
        {planet.description}
      </div>

      <div className="specs-grid">
        <div className="spec-item">
          <span className="spec-label">赤道直径</span>
          <span className="spec-value">{planet.diameterKm}</span>
        </div>
        <div className="spec-item">
          <span className="spec-label">
            {planet.id === 'sun' ? '太陽系中心距離' : '太陽からの相対距離'}
          </span>
          <span className="spec-value">
            {planet.distance === 0 ? '中心 (0 AU)' : `${(planet.distance * 0.031).toFixed(2)} AU`}
          </span>
        </div>
        <div className="spec-item">
          <span className="spec-label">公転周期</span>
          <span className="spec-value">{planet.orbitPeriodDays}</span>
        </div>
        <div className="spec-item">
          <span className="spec-label">自転周期</span>
          <span className="spec-value">{planet.rotationPeriodHours}</span>
        </div>

        {/* 環（リング）情報 */}
        {planet.ring && (
          <div className="spec-item" style={{ gridColumn: 'span 2' }}>
            <span className="spec-label" style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <Disc size={13} color="#facc15" />
              環（リング）構造
            </span>
            <span className="spec-value" style={{ color: '#facc15', fontSize: '0.85rem' }}>
              内径比率 {planet.ring.innerRadius} / 外径比率 {planet.ring.outerRadius} (氷・岩石群)
            </span>
          </div>
        )}

        {/* 衛星情報 */}
        {planet.moons && planet.moons.length > 0 && (
          <div className="spec-item" style={{ gridColumn: 'span 2' }}>
            <span className="spec-label" style={{ display: 'flex', alignItems: 'center', gap: '4px' }}>
              <Moon size={13} color="#94a3b8" />
              主要な衛星
            </span>
            <span className="spec-value" style={{ fontSize: '0.85rem' }}>
              {planet.moons.map((m) => `${m.name} (半径: ${m.radius} / 距離: ${m.distance})`).join(', ')}
            </span>
          </div>
        )}

        <div className="spec-item" style={{ gridColumn: 'span 2' }}>
          <span className="spec-label">表面温度 / 大気環境</span>
          <span className="spec-value" style={{ color: '#38bdf8' }}>
            {planet.temperature}
          </span>
        </div>
      </div>

      <button
        type="button"
        className="btn-control btn-reset"
        style={{ width: '100%', marginTop: '4px' }}
        onClick={onClose}
      >
        <ExternalLink size={14} />
        追尾を解除して全体へ戻る
      </button>
    </div>
  );
};

export default PlanetInfoPanel;

import { useState, useMemo, useEffect, useCallback } from 'react';
import { SolarSystemSettings } from './types';
import { ALL_CELESTIAL_BODIES } from './solarData';
import SolarCanvas from './SolarCanvas';
import Controls from './Controls';
import PlanetInfoPanel from './PlanetInfoPanel';
import './index.css';

const DEFAULT_SETTINGS: SolarSystemSettings = {
  isPlaying: true,
  speedMultiplier: 1.0,
  showOrbits: true,
  showLabels: true,
  labelMode: 'all',
  selectedPlanetId: null
};

const App = () => {
  const [settings, setSettings] = useState<SolarSystemSettings>(DEFAULT_SETTINGS);
  const [resetTrigger, setResetTrigger] = useState<number>(0);

  const handleUpdateSettings = useCallback((partial: Partial<SolarSystemSettings>) => {
    setSettings((prev) => ({
      ...prev,
      ...partial
    }));
  }, []);

  const handleSelectPlanet = useCallback((planetId: string | null) => {
    setSettings((prev) => ({
      ...prev,
      selectedPlanetId: planetId
    }));
  }, []);

  const handleResetView = useCallback(() => {
    setSettings((prev) => ({
      ...prev,
      selectedPlanetId: null
    }));
    setResetTrigger((prev) => prev + 1);
  }, []);

  // グローバルキーボードショートカット (Spaceで再生/停止、Rで全体俯瞰リセット、Escで追尾解除、0〜8で天体クイック選択)
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      const target = e.target as HTMLElement | null;
      if (
        target instanceof HTMLInputElement ||
        target instanceof HTMLTextAreaElement ||
        target instanceof HTMLSelectElement
      ) {
        return;
      }

      if (e.code === 'Space') {
        // ボタンにフォーカスがある場合、ブラウザ標準のクリック動作との二重発火を防止
        if (target instanceof HTMLButtonElement) {
          return;
        }
        e.preventDefault();
        setSettings((prev) => ({
          ...prev,
          isPlaying: !prev.isPlaying
        }));
      } else if (e.key === 'r' || e.key === 'R') {
        e.preventDefault();
        handleResetView();
      } else if (e.key === 'Escape') {
        e.preventDefault();
        setSettings((prev) => {
          if (prev.selectedPlanetId !== null) {
            return { ...prev, selectedPlanetId: null };
          }
          return prev;
        });
      } else if (e.key >= '0' && e.key <= '8') {
        const num = parseInt(e.key, 10);
        if (num < ALL_CELESTIAL_BODIES.length) {
          e.preventDefault();
          const targetBody = ALL_CELESTIAL_BODIES[num];
          setSettings((prev) => ({
            ...prev,
            selectedPlanetId: prev.selectedPlanetId === targetBody.id ? null : targetBody.id
          }));
        }
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [handleResetView]);

  const selectedPlanetData = useMemo(() => {
    if (!settings.selectedPlanetId) return null;
    return ALL_CELESTIAL_BODIES.find((b) => b.id === settings.selectedPlanetId) || null;
  }, [settings.selectedPlanetId]);

  return (
    <div className="app-container">
      {/* 画面左上タイトルオーバーレイ */}
      <header className="header-overlay">
        <h1 className="app-title">SOLAR SYSTEM 3D</h1>
        <span className="app-subtitle">インタラクティブ太陽系シミュレーター</span>
      </header>

      {/* 3D レンダリングキャンバス（resetTriggerをkeyにしてカメラアングル・距離を全体俯瞰へ初期化） */}
      <SolarCanvas
        key={resetTrigger}
        settings={settings}
        onSelectPlanet={handleSelectPlanet}
      />

      {/* 選択された天体の詳細スペックカード */}
      <PlanetInfoPanel
        planet={selectedPlanetData}
        onClose={() => handleSelectPlanet(null)}
      />

      {/* 操作HUDコントロールパネル */}
      <Controls
        settings={settings}
        onUpdateSettings={handleUpdateSettings}
        onResetView={handleResetView}
      />
    </div>
  );
};

export default App;
